def parse_date(raw: str) -> date:
    """Read a Borough ``value_date`` field, which is ISO ``YYYY-MM-DD``."""
    text = raw.strip()
    if not _ISO_DATE.match(text):
        raise LedgerParseError(f"Borough date {raw!r} is not YYYY-MM-DD")
    try:
        return date.fromisoformat(text)
    except ValueError as exc:
        raise LedgerParseError(f"Borough date {raw!r} is not a real date") from exc


